import atexit
import http.client
import json
from pathlib import Path
from types import SimpleNamespace

import pytest

from company_wiki.automation.narrative_model_caller import BudgetedNarrativeCaller
from company_wiki.automation.narrative_http_model import NarrativeHTTPModel
from company_wiki.automation.store import AutomationStore
from tools.document_understanding_benchmark import holdout_acceptance_observer as observer
from tools.document_understanding_benchmark import holdout_acceptance_contracts as contracts


@pytest.fixture
def seam(tmp_path,monkeypatch):
    config=tmp_path/'observer.json'
    value={'receipt_dir':str(tmp_path),'stage':'cache','allow_local_model_http':False}
    config.write_text(json.dumps(value))
    monkeypatch.setenv('CWP_HOLDOUT_CONTROLLER',str(config))
    monkeypatch.setattr(observer,'_INSTALLED',False)
    callbacks=[]
    monkeypatch.setattr(atexit,'register',callbacks.append)
    native=[]
    posted=[]
    monkeypatch.setattr(BudgetedNarrativeCaller,'generate',lambda *a:native.append('one') or ('response','usage'))
    monkeypatch.setattr(http.client.HTTPConnection,'request',lambda *a,**k:posted.append('one'))
    for cls,name in [(BudgetedNarrativeCaller,'_recover'),(NarrativeHTTPModel,'replay_response'),(AutomationStore,'finish_attempt')]:
        monkeypatch.setattr(cls,name,getattr(cls,name))
    body=json.dumps({'model':'synthetic','messages':[{'role':'system','content':'synthetic'},
      {'role':'user','content':json.dumps({'schema_version':'narrative-model-request/5','material':{'tasks':[]}})}]}).encode()
    monkeypatch.setattr(contracts,'request_preflight',lambda *a:(body,{'http_body_sha256':'a'*64}))
    context=SimpleNamespace(attempt=SimpleNamespace(attempt_id='one'),job=SimpleNamespace(job_id='one'))
    caller=SimpleNamespace(_model=None,_run_id='one',_store=SimpleNamespace(reservations_for_run=lambda _:[]))
    return SimpleNamespace(root=tmp_path,config=config,config_value=value,callbacks=callbacks,native=native,
      posted=posted,body=body,caller=caller,context=context)


@pytest.mark.parametrize('fault',['read','partial_write','publish'])
def test_input_observation_faults_remain_unknown_and_never_enable_second_post(seam,monkeypatch,capsys,fault):
    path=seam.root/'model-input.json'
    if fault=='read':
        path.write_bytes(seam.body)
    old_read,old_write,old_replace=Path.read_bytes,Path.write_bytes,observer.os.replace
    def read(p):
        if p.name=='model-input.json' and fault=='read':
            raise OSError('synthetic diagnostic read')
        return old_read(p)
    def write(p,body):
        if p.name=='model-input.json' and fault=='partial_write':
            old_write(p,body[:7])
            raise OSError('synthetic partial diagnostic write')
        return old_write(p,body)
    def replace(source,destination):
        if Path(destination).name=='model-input.json' and fault=='publish':
            raise OSError('synthetic diagnostic publish')
        return old_replace(source,destination)
    monkeypatch.setattr(Path,'read_bytes',read)
    monkeypatch.setattr(Path,'write_bytes',write)
    monkeypatch.setattr(observer.os,'replace',replace)
    observer.install()
    assert BudgetedNarrativeCaller.generate(seam.caller,seam.context,None)==('response','usage')
    http.client.HTTPConnection('offline.invalid').request('POST','/',body=seam.body)
    with pytest.raises(RuntimeError,match='HOLDOUT_SECOND_POST_REFUSED'):
        http.client.HTTPConnection('offline.invalid').request('POST','/',body=seam.body)
    assert seam.native==['one'] and seam.posted==['one']
    for callback in seam.callbacks:callback()
    assert 'HOLDOUT_OBSERVATION_INCOMPLETE' in capsys.readouterr().err
    assert not list(seam.root.glob('.model-input-*'))
    if fault!='read':assert not path.exists()


@pytest.mark.parametrize('entry',['generate','http'])
def test_successfully_observed_different_request_remains_a_true_mismatch(seam,entry):
    path=seam.root/'model-input.json'
    path.write_bytes(b'known different bytes')
    observer.install()
    with pytest.raises(RuntimeError,match='HOLDOUT_MODEL_INPUT_CHANGED'):
        if entry=='generate':BudgetedNarrativeCaller.generate(seam.caller,seam.context,None)
        else:http.client.HTTPConnection('offline.invalid').request('POST','/',body=seam.body)
    assert seam.native==[] and seam.posted==[]
    assert not (seam.root/'post-once').exists() and path.read_bytes()==b'known different bytes'


def test_unknown_paid_pin_cannot_be_invented_from_an_observer_io_fault(seam,monkeypatch,capsys):
    seam.config_value['stage']='after_paid'
    seam.config.write_text(json.dumps(seam.config_value))
    old_write=Path.write_bytes
    def fail(p,value):
        if p.name=='model-input.json':raise OSError('synthetic diagnostic failure')
        return old_write(p,value)
    monkeypatch.setattr(Path,'write_bytes',fail)
    observer.install()
    with pytest.raises(RuntimeError,match='HOLDOUT_PAID_PIN_NOT_DURABLE'):
        BudgetedNarrativeCaller.generate(seam.caller,seam.context,None)
    assert seam.native==['one'] and seam.posted==[]
    for callback in seam.callbacks:callback()
    assert 'HOLDOUT_OBSERVATION_INCOMPLETE' in capsys.readouterr().err
